-- =====================================================================
-- Horilla HR: payroll-only schema (PostgreSQL)
--
-- Every table needed to run payroll and nothing else: 259 tables, with
-- their sequences, primary keys, unique constraints, indexes and foreign
-- keys. Loads into an empty database; no foreign key points outside it.
--
-- Included apps (table count):
--   Payroll stack ..... payroll (39), employee (26), attendance (21),
--                       leave (31), base (74)
--   asset (17) ........ payroll's migrations depend on it and loans can
--                       reference an asset (asset fines)
--   report (8) ........ Payroll Reports; the payroll-only build keeps it
--                       on (ENABLED_MODULES=payroll-only)
--   Horilla support ... horilla_auth (3), horilla_theme (2),
--                       horilla_audit (4), horilla_documents (3),
--                       horilla_views (6), horilla_automations (3),
--                       horilla_tour (3), accessibility (2)
--                       (imported at module level by base/employee, or
--                       wired into the root URLconf / context processors)
--   Django/3rd party .. auth, admin, contenttypes, sessions, sites,
--                       notifications, auditlog, django_apscheduler,
--                       axes, token_blacklist
--
-- Left out: recruitment, onboarding, offboarding, pms, project, helpdesk,
-- biometric, facedetection, geofencing, horilla_meet, whatsapp,
-- horilla_ldap, horilla_backup, horilla_dbtemplate.
--
-- Generated with `pg_dump --schema-only` from a database built by running
-- `manage.py migrate` on this repository, so it matches the migrations.
-- Regenerate it the same way after model changes; do not hand-edit.
-- To stand up a working database, prefer `manage.py migrate`: this file
-- does not populate django_migrations.
-- =====================================================================

